Debounce utility (vanilla JS or React):

```javascript
function debounce(fn, delay) {
  let timeoutId;
  return function (...args) {
    clearTimeout(timeoutId);
    timeoutId = setTimeout(() => fn(...args), delay);
  };
}

// Usage
const searchInput = document.querySelector('input[type="search"]');
const handleSearch = debounce(async (query) => {
  const response = await fetch(`/api/search?q=${encodeURIComponent(query)}`);
  const results = await response.json();
  // Update UI with results
}, 300);

searchInput.addEventListener('input', (e) => {
  handleSearch(e.target.value);
});
```

React hook version:

```javascript
function useDebounce(callback, delay) {
  const timeoutRef = useRef();

  return useCallback((...args) => {
    clearTimeout(timeoutRef.current);
    timeoutRef.current = setTimeout(() => callback(...args), delay);
  }, [callback, delay]);
}

// In component
const [query, setQuery] = useState('');
const [results, setResults] = useState([]);

const debouncedSearch = useDebounce(async (q) => {
  if (!q) return;
  const res = await fetch(`/api/search?q=${encodeURIComponent(q)}`);
  setResults(await res.json());
}, 300);

return (
  <input
    type="search"
    value={query}
    onChange={(e) => {
      setQuery(e.target.value);
      debouncedSearch(e.target.value);
    }}
  />
);
```

The 300ms delay is typical; adjust to your needs. Each keystroke resets the timer, so the API fires only after the user stops typing for that interval.
